mapper.select:
select id, name, room, begin_date as beginDate, end_date as endDate, master_id as masterId, subject, create_time as createTime, update_time as updateTime from clazz c
c.name like concat('%',#{name},'%')
and c.end_date between #{begin} and #{end}

select count(*) from clazz c 

    c.name like concat('%',#{name},'%')


    and c.end_date between #{begin} and #{end}
